							<textarea
								v-model="alasanTolak"
								rows="4"
								class="w-full resize-none rounded-xl border border-ui-line-gray-200 px-3 py-2.5 text-sm text-ui-ink-gray-900 focus:border-ui-line-gray-200 focus:outline-none focus:ring-0"
							></textarea>

							<div class="mt-4 flex gap-2">
								<button
									type="button"
									class="flex-1 rounded-full border border-ui-line-gray-200 py-3 text-sm font-semibold text-ui-ink-gray-600"
									@click="batalTolak()"
								>
									Batal
								</button>
								<button
									type="button"
									:disabled="!alasanTolak.trim() || !!applying"
									class="flex-1 rounded-full bg-red-600 py-3 text-sm font-semibold text-white disabled:opacity-50"
									@click="jalankan(aksiTolak, alasanTolak.trim())"
								>
									Tolak Pengajuan
								</button>
							</div>
						</div>
					</Transition>
				</div>
			</Transition>
		</Teleport>
	</div>
</template>

<script setup>
import { computed, onMounted, ref } from 'vue'
import { createResource, toast } from 'frappe-ui'
import { statusBadge, rentang, angka, tanggal } from '../data/cutiStatus'
import { openAttachment } from '../composables/pdfViewer'

const props = defineProps({ name: { type: String, required: true } })

const d = ref(null)
const loading = ref(true)
const applying = ref('')
const actionsOpen = ref(false)
const tolakOpen = ref(false)
const aksiTolak = ref('')
const alasanTolak = ref('')
const bagiOpen = ref(false)
const aksiBagi = ref('')
const bagiHutang = ref(0)
const bagiNonPay = ref(0)
const inputFile = ref(null)
const unggah = ref(false)

const detailRes = createResource({
	url: 'juragan.api.portal.cuti.get_detail',
	method: 'GET',
	auto: false,
	makeParams: () => ({ name: props.name }),
	onSuccess: (data) => {
		d.value = data
	},
})

const errorMessage = computed(() => {
	if (!detailRes.error) return ''
	const e = detailRes.error
	return e?.messages?.[0] || e?.message || 'Gagal memuat pengajuan.'
})

const adaAksi = computed(() => !!d.value?.actions?.length)

// Kelebihan dianggap sudah diputuskan bila pembagiannya menutup seluruhnya.
const sudahDibagi = computed(() => {
	const x = d.value
	if (!x?.hari_kelebihan) return false
	return Math.abs(x.hari_hutang_cuti + x.hari_non_pay - x.hari_kelebihan) < 0.001
})

const bagiTotal = computed(() => Number(bagiHutang.value || 0) + Number(bagiNonPay.value || 0))
const bagiPas = computed(
	() =>
		Number(bagiHutang.value || 0) >= 0 &&
		Number(bagiNonPay.value || 0) >= 0 &&
		Math.abs(bagiTotal.value - Number(d.value?.hari_kelebihan || 0)) < 0.001
)

/**
 * Tiga tahap tetap: diajukan karyawan → diperiksa atasan → diputuskan HR.
 * Tahap atasan disembunyikan bila karyawannya memang tidak punya atasan,
 * supaya garis waktunya tidak memperlihatkan langkah yang tidak akan terjadi.
 */
const tahapan = computed(() => {
	const x = d.value
	if (!x) return []
	const s = x.status
	const out = []

	out.push({
		label: 'Diajukan karyawan',
		detail:
			s === 'Draft' ? 'Masih draft — belum dikirim' : `Dibuat ${tanggal(x.posting_date)}`,
		state: s === 'Draft' ? 'active' : 'done',
	})

	if (x.atasan && !x.pemohon_hr) {
		let state = 'todo'
		let detail = `Menunggu ${x.atasan}`
		if (x.disetujui_atasan) {
			const ditolak = s === 'Rejected' && !x.leave_approver
			state = ditolak ? 'reject' : 'done'
			detail = `${ditolak ? 'Ditolak' : 'Disetujui'} ${x.disetujui_atasan}`
		} else if (s === 'Menunggu Approval Atasan') {
			state = 'active'
		}
		out.push({ label: 'Persetujuan atasan', detail, state })
	}

	// Tahap HR. Dilewati bila pemohonnya sendiri orang HR — mereka langsung ke
	// Direktur, jadi menampilkan langkah yang tidak akan terjadi hanya menyesatkan.
	if (!x.pemohon_hr) {
		let st = 'todo'
		let detail = 'Menunggu HR'
		if (x.leave_approver) {
			const ditolak = s === 'Rejected' && !x.disetujui_direktur
			st = ditolak ? 'reject' : 'done'
			detail = `${ditolak ? 'Ditolak' : 'Disetujui'} ${x.leave_approver}`
		} else if (s === 'Menunggu Approval HR') {
			st = 'active'
		} else if (s === 'Rejected') {
			detail = 'Tidak sampai ke HR'
		}
		out.push({ label: 'Persetujuan HR', detail, state: st })
	}

	// Tahap akhir: Direktur memutuskan seluruh pengajuan.
	let dirState = 'todo'
	let dirDetail = 'Menunggu Direktur'
	if (x.disetujui_direktur) {
		dirState = s === 'Rejected' ? 'reject' : 'done'
		dirDetail = `${s === 'Rejected' ? 'Ditolak' : 'Disetujui'} ${x.disetujui_direktur}`
	} else if (s === 'Menunggu Approval Direktur') {
		dirState = 'active'
	} else if (s === 'Rejected') {
		dirDetail = 'Tidak sampai ke Direktur'
	}
	out.push({ label: 'Keputusan Direktur', detail: dirDetail, state: dirState })

	// Tahap tambahan yang hanya ada bila cutinya melebihi saldo: pemohon
	// menanggung konsekuensinya, jadi ia yang mengucapkan kata terakhir.
	if (x.hari_kelebihan) {
		let st = 'todo'
		let detail = 'Menunggu jawaban pemohon'
		if (x.keputusan_karyawan === 'Setuju') {
			st = 'done'
			detail = 'Diterima pemohon'
		} else if (x.keputusan_karyawan === 'Tidak Setuju') {
			st = 'reject'
			detail = 'Ditolak pemohon'
		} else if (s === 'Menunggu Persetujuan Karyawan') {
			st = 'active'
		} else if (s === 'Rejected') {
			detail = 'Tidak sampai ke pemohon'
		}
		out.push({ label: 'Persetujuan pemohon', detail, state: st })
	}

	if (s === 'Cancelled') {
		out.push({ label: 'Dibatalkan', detail: 'Pengajuan dibatalkan', state: 'reject' })
	}
	return out
})

function namaFile(url) {
	if (!url) return ''
	const bersih = String(url).split('?')[0]
	return decodeURIComponent(bersih.substring(bersih.lastIndexOf('/') + 1)) || bersih
}

function pilihFile() {
	if (!inputFile.value) return
	inputFile.value.value = ''
	inputFile.value.click()
}

const mcRes = createResource({
	url: 'juragan.api.portal.cuti.lampirkan_mc',
	method: 'POST',
})

// Berkasnya diunggah dulu, baru ditunjuk dokumennya — server yang menautkan
// keduanya supaya approver ikut bisa membukanya.
async function simpanMc(fileUrl) {
	await mcRes.submit({ name: props.name, file_url: fileUrl })
	await detailRes.fetch()
}

async function unggahMc(e) {
	const file = e.target.files?.[0]
	if (!file) return
	const MAKS_MB = 3
	if (file.size > MAKS_MB * 1024 * 1024) {
		toast.error(`Ukuran file maksimal ${MAKS_MB} MB.`)
		return
	}
	unggah.value = true
	try {
		const fd = new FormData()
		fd.append('file', file, file.name)
		fd.append('is_private', '1')
		const res = await fetch('/api/method/upload_file', {
			method: 'POST',
			credentials: 'include',
			headers: {
				Accept: 'application/json',
				'X-Frappe-CSRF-Token': window.csrf_token || '',
			},
			body: fd,
		})
		const json = await res.json().catch(() => ({}))
		if (!res.ok) throw new Error(json?.exception || json?.message || `HTTP ${res.status}`)
		await simpanMc(json.message?.file_url || '')
		toast.success('Surat dokter terlampir')
	} catch (err) {
		toast.error(err?.messages?.[0] || err.message || 'Gagal mengunggah lampiran.')
	} finally {
		unggah.value = false
	}
}

async function hapusMc() {
	if (unggah.value) return
	if (!window.confirm('Hapus lampiran surat dokter?')) return
	unggah.value = true
	try {
		await simpanMc('')
		toast.success('Lampiran dihapus')
	} catch (err) {
		toast.error(err?.messages?.[0] || err.message || 'Gagal menghapus lampiran.')
	} finally {
		unggah.value = false
	}
}

function merah(a) {
	return /reject|tolak|cancel|batal|tidak setuju/i.test(a || '')
}
function labelAksi(a) {
	return (
		{
			Approve: 'Setujui',
			Reject: 'Tolak',
			Cancel: 'Batalkan',
			'Ajukan Cuti': 'Ajukan Cuti',
			Setuju: 'Terima Keputusan',
			'Tidak Setuju': 'Tolak Keputusan',
		}[a] || a
	)
}

// Cancel perlu konfirmasi: dari status Approved ia memulihkan saldo dan
// membatalkan Kehadiran — bukan sekadar mengubah label.
function butuhKonfirmasi(a) {
	return a === 'Cancel' || a === 'Tidak Setuju'
}

// Penolakan tidak boleh langsung jalan: alasannya diminta dulu, karena yang
// ditolak berhak tahu kenapa. Yang menentukan tujuan transisinya, bukan nama
// aksinya — nama bisa diubah di Workflow, statusnya tidak.
function pilihAksi(a) {
	if (a.next_state === 'Rejected') {
		aksiTolak.value = a.action
		alasanTolak.value = ''
		tolakOpen.value = true
		return
	}
	// Menuju tahap pemohon berarti Direktur harus menentukan dulu perlakuan
	// hari yang melebihi saldo — persetujuannya tidak berarti apa-apa tanpa itu.
	if (a.next_state === 'Menunggu Persetujuan Karyawan') {
		aksiBagi.value = a.action
		bagiHutang.value = Number(d.value?.hari_kelebihan || 0)
		bagiNonPay.value = 0
		bagiOpen.value = true
		return
	}
	jalankan(a.action)
}

function batalBagi() {
	if (applying.value) return
	bagiOpen.value = false
	aksiBagi.value = ''
}

function batalTolak() {
	if (applying.value) return
	tolakOpen.value = false
	aksiTolak.value = ''
	alasanTolak.value = ''
}

async function jalankan(action, alasan = '', pembagian = null) {
	if (applying.value) return
	if (
		butuhKonfirmasi(action) &&
		!window.confirm(
			action === 'Tidak Setuju'
				? 'Tolak dan batalkan pengajuan ini?'
				: 'Batalkan pengajuan cuti ini?'
		)
	)
		return
	applying.value = action
	try {
		await createResource({
			url: 'juragan.api.portal.cuti.apply_transition',
			method: 'POST',
		}).submit({
			name: props.name,
			action,
			...(alasan ? { alasan } : {}),
			...(pembagian || {}),
		})
		await detailRes.fetch()
		toast.success(
			{
				Reject: 'Pengajuan ditolak',
				Cancel: 'Pengajuan dibatalkan',
				Setuju: 'Cuti disetujui dan berlaku',
				'Tidak Setuju': 'Pengajuan dibatalkan',
			}[action] || 'Pengajuan disetujui'
		)
	} catch (e) {
		toast.error(e?.messages?.[0] || e?.message || 'Gagal memproses aksi.')
	} finally {
		applying.value = ''
		actionsOpen.value = false
		tolakOpen.value = false
		bagiOpen.value = false
	}
}

onMounted(async () => {
	try {
		await detailRes.fetch()
	} finally {
		loading.value = false
	}
})
</script>
